"""Record digests and scope for read-only emulator context used offline."""
from pathlib import Path
import struct,json,hashlib
ROOT=Path(__file__).resolve().parents[1]
DIR=ROOT/'.work/camscanner/shell-unpacked/x86'
def main():
    files=[]
    for name in ('android-linker','android-libc.so','android-zygote-auxv.bin','android-zygote-maps.txt','android-zygote-maps.lf.bin','android-zygote-status.txt','android-zygote-wchan.txt','android-properties.json','probe-shell-sysconf','android-libart.so','android-libart-stat.bin','android-liblog.so','android-liblog-stat.bin','probe-shell-stat','android-time.json','probe-shell-access','android-access.json','android-tty-drivers.txt','counterfactual-nonemulator-properties.json'):
        p=DIR/name;b=p.read_bytes();files.append({'path':str(p.relative_to(ROOT)),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()})
    aux=dict(struct.iter_unpack('<II',(DIR/'android-zygote-auxv.bin').read_bytes()))
    result={'device':'emulator-5580','pid':309,'process':'zygote','acquisition':'adb pull /apex/com.android.runtime/bin/linker; adb pull /apex/com.android.runtime/lib/bionic/libc.so; adb shell cat /proc/309/auxv | base64; adb shell cat /proc/309/maps; adb shell getprop full inventory and explicit absent property queries','auxv':{str(k):hex(v) for k,v in aux.items()},'property_count':len(json.loads((DIR/'android-properties.json').read_text())),'files':files,'scope':'Read-only context inventory shared by separate offline experiments. Only observed AT_BASE (7) is returned to emulated getauxval. Linker PT_LOAD file bytes mapped at observed base; linker live relocations, debugger state, ART and auxiliary pointer referents absent. libc PT_LOAD and dynsym mapped at synthetic base/handle 0x40000000, with no actual Android dlopen or libc constructors. Individual experiment evidence reports its own stopping point and explicit clone/proc/JNI models. TLS, allocator and page syscalls remain explicit emulation stubs; replayed zygote proc files are not original application process state.'}
    (ROOT/'output/camscanner-reverse/shell-emulator-context-evidence.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
    art_context={'device':'emulator-5580','acquisition':['adb pull /apex/com.android.art/lib/libart.so','adb pull /system/lib/liblog.so','i686 Android NDK probe-shell-stat(path) through adb exec-out, raw stdout captured by Python subprocess (not text redirection)','adb shell date +%s'],'stat_probe_source':'scanner/probe_shell_stat.c','stat_probe_compiler':'Android NDK r27d clang --target=i686-linux-android30','stat_struct_bytes':96,'files':[f for f in files if any(key in f['path'] for key in ('libart','liblog','probe-shell-stat','android-time'))],'scope':'Read-only snapshots of actual emulator system files and exact 32-bit libc stat structs. ART-file emulation optionally maps PT_LOAD original file bytes without dynamic relocations, live JVM state, SELinux or original application memory.'}
    (ROOT/'output/camscanner-reverse/shell-art-file-context-evidence.json').write_text(json.dumps(art_context,indent=2),encoding='utf-8')
    correction={'device':'emulator-5580','probe_source':'scanner/probe_shell_sysconf.c','compiler':'Android NDK r27d clang --target=i686-linux-android30','actual_output':'30 1 0\n39 4096 0\n40 4096 0\n','columns':['sysconf_argument','result','errno'],'correction':'Prior normal constructor stop evidence modeled argument30 using Linux _SC_PAGESIZE=30 and returned4096. Android bionic argument30 is _SC_XOPEN_ENH_I18N and returns1. Current clone/proc/JNI experiments use observed values; old normal-stop evidence retained as historical assumption, not correct Android semantics.'}
    (ROOT/'output/camscanner-reverse/shell-sysconf-correction-evidence.json').write_text(json.dumps(correction,indent=2),encoding='utf-8')
    print('Saved context evidence for',len(files),'files; AT_BASE',hex(aux[7]))
if __name__=='__main__':main()
